  "bestCut.consent": "Pour trouver votre meilleure prise, les fichiers vidéo sélectionnés sont envoyés en entier à Veyrnox.ai puis à un service de transcription pour analyser leur audio. Le script et les notes restent sur ce téléphone. La suppression des envois temporaires est prévue après 24 heures ; le nettoyage peut prendre plus de temps. Les transcriptions sont conservées jusqu’à 30 jours pour éviter une double facturation. Supprimer le compte supprime les transcriptions. Les originaux de la bibliothèque et les sauvegardes de projets suivent leur propre cycle de conservation. Si personne ne parle, rien n’est facturé.",
