  "helpGuides.content.first-generation.s1.title": "Ouvrir le studio",
  "helpGuides.content.first-generation.s2.body": "La liste à droite affiche chaque modèle avec son prix en crédits. Les modèles d’image, de vidéo et d’audio puisent tous dans le même solde.",
  "helpGuides.content.first-generation.s2.title": "Choisissez un modèle",
  "helpGuides.content.first-generation.s3.body": "Décrivez ce que vous voulez voir. Pour une vidéo, indiquez ce qui bouge et comment la caméra se déplace.",
  "helpGuides.content.first-generation.s3.title": "Rédigez le prompt",
  "helpGuides.content.first-generation.s4.body": "Le total s’affiche au-dessus du bouton Générer avant que vous n’appuyiez. Un clip de 10 s coûte le double d’un clip de 5 s, et choisir plusieurs images multiplie le prix par leur nombre.",
  "helpGuides.content.first-generation.s4.title": "Vérifiez le coût",
